package com.amora.app;
import android.app.*;import android.content.*;import android.content.pm.*;import android.os.*;import android.location.*;import android.hardware.*;import org.json.*;import java.net.*;import java.io.*;import java.util.*;
public class TrackingService extends Service implements LocationListener,SensorEventListener {
 static TrackingService active;final android.os.Handler handler=new android.os.Handler(android.os.Looper.getMainLooper());final java.util.concurrent.ExecutorService io=java.util.concurrent.Executors.newSingleThreadExecutor();LocationManager locations;SensorManager sensors;boolean locating=false,steps=false;volatile boolean running=true;final java.util.concurrent.atomic.AtomicBoolean syncing=new java.util.concurrent.atomic.AtomicBoolean();volatile Location latest;long lastUpload=0;String user="";static final String URL="https://qaiqflcxfxygynumapyp.supabase.co";
 final Runnable poll=new Runnable(){public void run(){if(!running)return;queueSync();handler.postDelayed(this,30000);}};
 @Override public void onCreate(){super.onCreate();active=this;locations=(LocationManager)getSystemService(LOCATION_SERVICE);sensors=(SensorManager)getSystemService(SENSOR_SERVICE);}
 boolean permission(String p){return checkSelfPermission(p)==PackageManager.PERMISSION_GRANTED;}
 @Override public int onStartCommand(Intent intent,int flags,int id){if(intent!=null&&"stop".equals(intent.getAction())){stopSharing();return START_NOT_STICKY;}if(intent==null){stopSelf();return START_NOT_STICKY;}boolean wantSteps=intent.getBooleanExtra("steps",false);if(!permission("android.permission.ACCESS_FINE_LOCATION")&&!permission("android.permission.ACCESS_COARSE_LOCATION")){NativeBridge.event("error","Permita a localização para iniciar o acompanhamento.");stopSelf();return START_NOT_STICKY;}
 steps=wantSteps&&(Build.VERSION.SDK_INT<29||permission("android.permission.ACTIVITY_RECOGNITION"));if(wantSteps&&!steps)NativeBridge.event("info","GPS ativado. Os passos precisam da permissão de atividade física.");PendingIntent stop=PendingIntent.getService(this,90,new Intent(this,TrackingService.class).setAction("stop"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification notification=NativeBridge.notification(this,"amora-tracking","(N)AMORA · acompanhamento ativo","Sua posição é compartilhada com seu vínculo. Toque em Parar para pausar.",stop);
 try{if(Build.VERSION.SDK_INT>=34)startForeground(190,notification,ServiceInfo.FOREGROUND_SERVICE_TYPE_LOCATION|(steps?ServiceInfo.FOREGROUND_SERVICE_TYPE_HEALTH:0));else startForeground(190,notification);}catch(Exception e){NativeBridge.event("error","Abra o Amora e ative o acompanhamento novamente.");stopSelf();return START_NOT_STICKY;}
 try{JSONObject session=new JSONObject(SecureStore.get(this));user=session.getString("user");getSharedPreferences("amora",0).edit().putLong("step."+user+".raw",-1).apply();}catch(Exception e){stopSelf();return START_NOT_STICKY;}
 getSharedPreferences("amora",0).edit().putBoolean("trackingActive",true).apply();try{if(!locating){for(String provider:Arrays.asList(LocationManager.GPS_PROVIDER,LocationManager.NETWORK_PROVIDER))if(locations.getAllProviders().contains(provider))locations.requestLocationUpdates(provider,15000,15,this);locating=true;}}catch(Exception e){NativeBridge.event("error","Ative a localização do aparelho e tente novamente.");}
 sensors.unregisterListener(this);if(steps){Sensor sensor=sensors.getDefaultSensor(Sensor.TYPE_STEP_COUNTER);if(sensor!=null)sensors.registerListener(this,sensor,SensorManager.SENSOR_DELAY_NORMAL);else NativeBridge.event("info","Este celular não tem sensor de passos disponível.");}
 handler.removeCallbacks(poll);handler.post(poll);NativeBridge.event("tracking",true);return START_NOT_STICKY;}
 @Override public void onLocationChanged(Location l){if(l.getTime()<System.currentTimeMillis()-120000)return;latest=l;if(System.currentTimeMillis()-lastUpload>15000){lastUpload=System.currentTimeMillis();queueSync();}}
 @Override public void onProviderDisabled(String p){NativeBridge.event("error","O GPS do aparelho foi desligado. Ative a localização para atualizar o mapa.");}
 @Override public void onProviderEnabled(String p){}
 @Override public void onStatusChanged(String p,int s,Bundle b){}
 @Override public void onSensorChanged(SensorEvent e){if(!steps||user.isEmpty())return;android.content.SharedPreferences p=getSharedPreferences("amora",0);String day=new java.text.SimpleDateFormat("yyyy-MM-dd",java.util.Locale.US).format(new Date()),prefix="step."+user+".";String previousDay=p.getString(prefix+"day",day);long raw=(long)e.values[0],previous=p.getLong(prefix+"raw",-1);int total=p.getInt(prefix+day,0);if(previous>=0&&raw>=previous&&day.equals(previousDay))total+=(int)Math.min(10000,raw-previous);p.edit().putLong(prefix+"raw",raw).putString(prefix+"day",day).putInt(prefix+day,total).apply();}
 @Override public void onAccuracyChanged(Sensor s,int a){}
 JSONObject session()throws Exception{JSONObject s=new JSONObject(SecureStore.get(this));if(s.getLong("expires")<System.currentTimeMillis()/1000+90){JSONObject refreshed=request("/auth/v1/token?grant_type=refresh_token",new JSONObject().put("refresh_token",s.getString("refresh")),s,false);s.put("access",refreshed.getString("access_token")).put("refresh",refreshed.getString("refresh_token")).put("expires",refreshed.optLong("expires_at",System.currentTimeMillis()/1000+refreshed.optLong("expires_in",3600)));if(!running)throw new IOException("Stopped");s=new JSONObject(SecureStore.replace(this,s.toString(),user));NativeBridge.event("trackingSessionUpdated",true);}return s;}
 JSONObject request(String path,JSONObject payload,JSONObject session,boolean authenticated)throws Exception{HttpURLConnection c=(HttpURLConnection)new java.net.URL(URL+path).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("apikey",session.getString("key"));if(authenticated)c.setRequestProperty("Authorization","Bearer "+session.getString("access"));try{try(OutputStream out=c.getOutputStream()){out.write(payload.toString().getBytes("UTF-8"));}if(c.getResponseCode()>=400)throw new IOException("HTTP "+c.getResponseCode());try(InputStream in=c.getInputStream()){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);return new JSONObject(out.toString("UTF-8"));}}finally{c.disconnect();}}
 JSONObject rpc(JSONObject p,JSONObject s)throws Exception{return request("/rest/v1/rpc/namora_track",new JSONObject().put("payload",p),s,true);}
 void queueSync(){if(!running||!syncing.compareAndSet(false,true))return;io.execute(()->{try{sync();}finally{syncing.set(false);}});}
 void sync(){if(!running)return;try{JSONObject s=session(),snapshot=rpc(new JSONObject(),s);if(!snapshot.optBoolean("enabled")){handler.post(()->stopSelf());return;}if(latest!=null){Location l=latest;if(System.currentTimeMillis()-l.getTime()<120000)snapshot=rpc(new JSONObject().put("action","location").put("latitude",l.getLatitude()).put("longitude",l.getLongitude()).put("accuracy",(int)Math.ceil(l.getAccuracy())),s);}
 if(steps&&snapshot.optBoolean("steps_enabled")){Map<String,?> values=getSharedPreferences("amora",0).getAll();String prefix="step."+user+".";for(String k:values.keySet())if(k.startsWith(prefix)&&k.substring(prefix.length()).matches("[0-9]{4}-[0-9]{2}-[0-9]{2}")){String day=k.substring(prefix.length());try{java.util.Date date=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).parse(day);if(date==null||System.currentTimeMillis()-date.getTime()>35L*86400000)continue;rpc(new JSONObject().put("action","steps").put("day",day).put("steps",values.get(k)),s);}catch(Exception ignored){}}}
 JSONArray events=snapshot.getJSONArray("events");android.content.SharedPreferences p=getSharedPreferences("amora",0);String cursorKey="trackingCursor."+user;long cursor=p.getLong(cursorKey,-1),max=cursor;for(int i=0;i<events.length();i++){JSONObject event=events.getJSONObject(i);long id=event.getLong("id");if(cursor>=0&&id>cursor&&!user.equals(event.getString("user_id")))notifyEvent(event);max=Math.max(max,id);}p.edit().putLong(cursorKey,Math.max(0,max)).apply();NativeBridge.event("tracking",true);
 }catch(Exception e){if(e.getMessage()!=null&&(e.getMessage().contains("HTTP 401")||e.getMessage().contains("HTTP 403"))){handler.post(()->stopSelf());NativeBridge.event("error","Entre novamente no Amora para retomar o acompanhamento.");return;}NativeBridge.event("trackingError","Sem sincronização no momento. Os dados locais serão enviados quando a conexão voltar.");}}
 void notifyEvent(JSONObject e)throws Exception{if(Build.VERSION.SDK_INT>=33&&!permission("android.permission.POST_NOTIFICATIONS"))return;NotificationManager m=getSystemService(NotificationManager.class);m.createNotificationChannel(new NotificationChannel("amora-arrivals","Chegadas e SOS do vínculo",NotificationManager.IMPORTANCE_HIGH));PendingIntent open=PendingIntent.getActivity(this,91,new Intent(this,MainActivity.class).putExtra("route","map"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);String time=new java.text.SimpleDateFormat("HH:mm",Locale.getDefault()).format(java.time.Instant.parse(e.getString("created_at")).toEpochMilli());m.notify((int)(e.getLong("id")%100000)+200,new Notification.Builder(this,"amora-arrivals").setSmallIcon(R.drawable.amora_icon).setContentTitle(e.getString("kind").equals("sos")?"SOS · Seu amor pediu ajuda":"Chegou com carinho ♡").setContentText(e.getString("body")+" · "+time).setStyle(new Notification.BigTextStyle().bigText(e.getString("body")+" · "+time)).setContentIntent(open).setAutoCancel(true).build());}
 void stopSharing(){running=false;handler.removeCallbacks(poll);locations.removeUpdates(this);sensors.unregisterListener(this);getSharedPreferences("amora",0).edit().putBoolean("trackingActive",false).apply();io.execute(()->{try{rpc(new JSONObject().put("action","consent").put("enabled",false).put("steps_enabled",false),session());}catch(Exception ignored){}handler.post(()->stopSelf());});}
 @Override public void onDestroy(){running=false;active=null;handler.removeCallbacks(poll);if(locations!=null)locations.removeUpdates(this);if(sensors!=null)sensors.unregisterListener(this);getSharedPreferences("amora",0).edit().putBoolean("trackingActive",false).apply();io.shutdown();NativeBridge.event("tracking",false);super.onDestroy();}
 @Override public IBinder onBind(Intent i){return null;}
}
